mapper.select:
SELECT t.id, t.plan_id, t.base_id, b.base_name, p.title AS plan_title, p.plan_type, t.task_title, t.target_type, t.target_id, CASE WHEN t.target_type = 'pond' THEN COALESCE(po.pond_name, CONCAT(t.target_id, '号塘')) WHEN t.target_type = 'cage' THEN COALESCE(ci.cage_name, CONCAT('网箱#', t.target_id)) WHEN t.target_type = 'vsl' THEN COALESCE(vi.vsl_name, CONCAT('工船#', t.target_id)) ELSE CONCAT(t.target_id, '') END AS target_name, t.action_time, t.deadline_time, t.status, t.assignee_id, br.breeder_name AS assignee_name, t.cancel_reason, t.device_id, dev.device_name, t.device_action, t.priority, t.feed_variety, t.feed_amount, t.drug_name, t.dosage, t.withdrawal_days, t.weather_req, t.create_time, t.update_time, p.content_desc FROM prod_task t LEFT JOIN base_info b ON t.base_id = b.id LEFT JOIN pond_info po ON t.target_id = po.id AND t.target_type = 'pond' LEFT JOIN cage_info ci ON t.target_id = ci.id AND t.target_type = 'cage' LEFT JOIN vsl_info vi ON t.target_id = vi.id AND t.target_type = 'vsl' LEFT JOIN prod_plan p ON t.plan_id = p.id LEFT JOIN biz_breeder br ON t.assignee_id = br.id LEFT JOIN iot_device dev ON t.device_id = dev.id
WHERE t.is_delete = 0
AND t.plan_id = #{query.planId}
AND t.base_id = #{query.baseId}
AND t.target_type = #{query.targetType}
AND t.target_id = #{query.targetId}
AND t.status = #{query.status}
AND t.assignee_id = #{query.assigneeId}
AND p.plan_type = #{query.planType}
ORDER BY t.create_time DESC
